def unit_economics(cac, arpu_monthly, gross_margin, churn_monthly):
    # The verdict function: LTV/CAC and payback from first principles
    lifetime_months = 1 / churn_monthly
    ltv = arpu_monthly * gross_margin * lifetime_months
    ratio = ltv / cac
    payback = cac / (arpu_monthly * gross_margin)  # months
    verdict = "HEALTHY" if ratio >= 3 else "BREAKEVEN+" if ratio >= 1 else "BROKEN"
    return {"ltv": round(ltv, 2), "ltv_cac": round(ratio, 2),
            "payback_months": round(payback, 1), "verdict": verdict}

print(unit_economics(cac=60, arpu_monthly=10, gross_margin=1.0, churn_monthly=0.25))
# -> {'ltv': 40.0, 'ltv_cac': 0.67, 'payback_months': 6.0, 'verdict': 'BROKEN'}
